  default: () => ({ allProcessedResults: [] }),
}));

import runQuery from "~/utils/runQuery";

const extensionAPI = {} as OnloadArgs["extensionAPI"];

describe("runQuery", () => {
  beforeEach(() => {
    fireQuery.mockReset().mockResolvedValue([]);
    vi.stubGlobal("roamAlphaAPI", { util: { generateUID: () => "uid" } });
  });

  it("forwards local so callers can read blocks the backend has not synced", async () => {
    await runQuery({
      parentUid: "q",
      extensionAPI,
      inputs: { NODETEXT: "t" },
      local: true,
    });
    expect(fireQuery).toHaveBeenCalledWith(
      expect.objectContaining({ local: true, inputs: { NODETEXT: "t" } }),
    );
  });

  it("leaves local unset by default", async () => {
    await runQuery({ parentUid: "q", extensionAPI });
    expect(fireQuery.mock.calls[0][0].local).toBeUndefined();
  });
});

