// How long after triggerSmartblock resolves do its blocks appear locally?
const state = {};

export default {
  async run({ page }) {
    return page.evaluate(async () => {
      const api = window.roamAlphaAPI;
      const sb = window.roamjs?.extension?.smartblocks;
      if (!sb) return { error: "smartblocks not loaded" };
      const ts = Date.now();
      const srcPage = api.util.generateUID();
      const srcUid = api.util.generateUID();
      const h1 = api.util.generateUID();
      await api.data.page.create({ page: { title: `ENG-2362 sb src ${ts}`, uid: srcPage } });
      await api.data.block.create({ location: { "parent-uid": srcPage, order: 0 }, block: { string: "template", uid: srcUid } });
      await api.data.block.create({ location: { "parent-uid": srcUid, order: 0 }, block: { string: "Key Image", uid: h1, heading: 1 } });
      await api.data.block.create({ location: { "parent-uid": h1, order: 0 }, block: { string: "image goes here" } });
      await api.data.block.create({ location: { "parent-uid": srcUid, order: 1 }, block: { string: "Made <%DATE:today%>" } });
      const title = `ENG-2362 sb target ${ts}`;
      const target = api.util.generateUID();
      await api.data.page.create({ page: { title, uid: target } });
      const q = `[:find ?uid :in $ ?title :where [?p :node/title ?title] [?b :block/page ?p] [?h :block/children ?b] [?h :block/heading 1] [?b :block/uid ?uid]]`;
      const t0 = performance.now();
      const ret = await sb.triggerSmartblock({ srcUid, targetUid: target });
      const resolvedMs = performance.now() - t0;
      const atResolve = await api.data.async.fast.q(q, title);
      let visibleMs = null;
      while (performance.now() - t0 < 10000) {
        const r = await api.data.async.fast.q(q, title);
        if (r.length) { visibleMs = performance.now() - t0; break; }
        await new Promise((res) => setTimeout(res, 50));
      }
      const tree = api.pull("[:block/string :block/heading {:block/children ...}]", [":block/uid", target]);
      return { srcPage, target, ret, resolvedMs, atResolve, visibleMs, tree };
    }).then((v) => { Object.assign(state, v); return v; });
  },
  async cleanup({ page }) {
    for (const uid of [state.srcPage, state.target].filter(Boolean)) {
      await page.evaluate((u) => window.roamAlphaAPI.data.page.delete({ page: { uid: u } }), uid);
    }
  },
};

