// record triggerSmartblock + local query timing
window.__eng2362Ev = [];
const t0 = performance.now();
const sbObj = window.roamjs.extension.smartblocks;
if (sbObj) {
  const origT = sbObj.triggerSmartblock;
  window.__eng2362OrigT = origT;
  sbObj.triggerSmartblock = async (args) => {
    window.__eng2362Ev.push({ ev: "sb-start", at: performance.now() - t0, args });
    const r = await origT(args);
    const n = api.data.fast.q(`[:find ?b :in $ ?p :where [?pg :block/uid ?p] [?b :block/page ?pg]]`, args.targetUid).length;
    window.__eng2362Ev.push({ ev: "sb-resolved", at: performance.now() - t0, ret: r, localBlocks: n });
    return r;
  };
}
const origL = api.data.async.fast.q;
window.__eng2362OrigL = origL;
api.data.async.fast.q = async (q, ...args) => {
  const r = await origL(q, ...args);
  if (q.includes("NODETEXT")) window.__eng2362Ev.push({ ev: "local-q", at: performance.now() - t0, count: r.length, input: args[0] });
  return r;
};

if (window.__eng2362Sb) window.roamjs.extension.smartblocks = window.__eng2362Sb;
if (window.__eng2362OrigT) window.roamjs.extension.smartblocks.triggerSmartblock = window.__eng2362OrigT;
if (window.__eng2362OrigL) api.data.async.fast.q = window.__eng2362OrigL;

