// ENG-2362 on a legacy-tree graph: temporarily give Claim a QB key image + H1/child template, convert an image, restore.
import fs from "node:fs";
const NODE_TYPE_TEXT = process.env.ENG2362_NODE_TYPE || "Claim";
const TS = Date.now();
const state = { canvasTitle: `Canvas/ENG-2362 ak ${TS}`, nodeContent: `eng2362 ak ${TS}`, edits: null };
const logs = [];
const BACKUP = new URL("./ak-backup.json", import.meta.url);

const closeDialogs = async (page) => {
  for (let i = 0; i < 10; i++) {
    if (!(await page.locator(".bp3-dialog, .bp3-overlay-open").count())) return;
    await page.keyboard.press("Escape");
    await page.waitForTimeout(300);
  }
};

const SNAPSHOT = (uid) =>
  JSON.stringify(
    window.roamAlphaAPI.pull(
      "[:block/uid :block/string :block/order :block/heading :block/props {:block/children ...}]",
      [":block/uid", uid],
    ),
    (k, v) => (v && typeof v === "object" && !Array.isArray(v) ? Object.fromEntries(Object.entries(v).sort()) : Array.isArray(v) && v[0]?.[":block/order"] !== undefined ? [...v].sort((a, b) => a[":block/order"] - b[":block/order"]) : v),
  );

export default {
  async run({ page }) {
    page.on("console", (m) => {
      const t = m.text();
      if (/Roam Query|Inputs|🚨/i.test(t)) logs.push(t.slice(0, 1500));
    });
    await closeDialogs(page);
    const edits = await page.evaluate(async ({ nodeTypeText, ts, snapshotSrc }) => {
      const snapshot = new Function(`return (${snapshotSrc})`)();
      const api = window.roamAlphaAPI;
      const uid = () => api.util.generateUID();
      const node = window.roamjs.extension.queryBuilder.getDiscourseNodes().find((n) => n.text === nodeTypeText);
      if (!node) throw new Error(`no node type ${nodeTypeText}`);
      const typeUid = node.type;
      const original = snapshot(typeUid);
      const props = api.pull("[:block/props]", [":block/uid", typeUid])?.[":block/props"];
      if (props && Object.keys(props).length) throw new Error(`node page has block props; legacy-only module: ${JSON.stringify(props).slice(0, 200)}`);
      const kids = (u) => (api.pull("[{:block/children [:block/uid :block/string :block/order]}]", [":block/uid", u])?.[":block/children"] || []).sort((a, b) => a[":block/order"] - b[":block/order"]);
      const find = (u, text) => kids(u).find((c) => c[":block/string"].toLowerCase() === text.toLowerCase());
      const e = { typeUid, original, created: [], updated: [] };

      // Temp QB query: block in page titled NODETEXT whose parent is a Heading 1.
      const qPage = uid();
      await api.data.page.create({ page: { title: `ENG-2362 qb image query ${ts}`, uid: qPage } });
      e.qPage = qPage;
      const mk = async (parent, text, order = 0) => {
        const u = uid();
        await api.data.block.create({ location: { "parent-uid": parent, order }, block: { string: text, uid: u } });
        return u;
      };
      const qb = await mk(qPage, "{{query block}}");
      await mk(qb, "results", 0);
      const scratch = await mk(qb, "scratch", 1);
      await mk(scratch, "custom", 0);
      await mk(scratch, "selections", 1);
      const conds = await mk(scratch, "conditions", 2);
      const clause = async (order, s, r, t) => {
        const c = await mk(conds, "clause", order);
        await mk(await mk(c, "source", 0), s);
        await mk(await mk(c, "Relation", 1), r);
        await mk(await mk(c, "target", 2), t);
      };
      await clause(0, "node", "is in page with title", ":in NODETEXT");
      await clause(1, "node", "has parent", "h1");
      await clause(2, "h1", "has heading", "1");
      e.qb = qb;

      // Canvas settings in the legacy tree.
      let canvas = find(typeUid, "Canvas")?.[":block/uid"];
      if (!canvas) {
        canvas = await mk(typeUid, "Canvas", 99);
        e.created.push(canvas);
      }
      const setKey = async (key, value) => {
        const k = find(canvas, key);
        if (!k) {
          const ku = await mk(canvas, key, 99);
          await mk(ku, value);
          e.created.push(ku);
          return;
        }
        const child = kids(k[":block/uid"])[0];
        if (!child) {
          e.created.push(await mk(k[":block/uid"], value));
          return;
        }
        e.updated.push({ uid: child[":block/uid"], text: child[":block/string"] });
        await api.data.block.update({ block: { uid: child[":block/uid"], string: value } });
      };
      await setKey("key-image", "true");
      await setKey("key-image-option", "query-builder");
      await setKey("query-builder-alias", `((${qb}))`);

      // Template: H1 + placeholder child at the top.
      let template = find(typeUid, "Template")?.[":block/uid"];
      if (!template) {
        template = await mk(typeUid, "Template", 99);
        e.created.push(template);
      }
      const h1 = uid();
      await api.data.block.create({ location: { "parent-uid": template, order: 0 }, block: { string: "ENG-2362 Key Image", uid: h1, heading: 1 } });
      await mk(h1, "image goes here");
      e.created.push(h1);

      // Prove the query runs locally after the fix.
      window.__ak = { backend: 0, local: [] };
      const ob = api.data.backend.q.bind(api.data.backend);
      const ol = api.data.async.fast.q;
      window.__akRestore = () => { api.data.backend.q = ob; api.data.async.fast.q = ol; };
      api.data.backend.q = async (q, ...a) => { if (q.includes("NODETEXT")) window.__ak.backend++; return ob(q, ...a); };
      api.data.async.fast.q = async (q, ...a) => { const r = await ol(q, ...a); if (q.includes("NODETEXT")) window.__ak.local.push(r.length); return r; };
      e.canvasSettingsAfterSetup = window.roamjs.extension.queryBuilder.getDiscourseNodes().find((n) => n.text === nodeTypeText).canvasSettings;
      return e;
    }, { nodeTypeText: NODE_TYPE_TEXT, ts: TS, snapshotSrc: SNAPSHOT.toString() });
    state.edits = edits;
    fs.writeFileSync(BACKUP, JSON.stringify(edits, null, 1));

    const setup = await page.evaluate(async ({ canvasTitle }) => {
      const api = window.roamAlphaAPI;
      const img = api.data.fast.q(`[:find ?s :where [?b :block/string ?s] [(clojure.string/includes? ?s "firebasestorage")] [(clojure.string/includes? ?s ".png")] [(clojure.string/starts-with? ?s "![](")]]`).slice(0, 1)[0]?.[0];
      const src = img ? img.match(/\((https:[^)]+)\)/)[1] : null;
      const uid = api.util.generateUID();
      await api.data.page.create({ page: { title: canvasTitle, uid } });
      await api.ui.mainWindow.openPage({ page: { uid } });
      return { src, canvasUid: uid };
    }, state);
    state.canvasUid = setup.canvasUid;
    if (!setup.src) throw new Error("no firebase png found in graph to use as image");
    await page.waitForFunction((t) => !!window.tldrawApps?.[t], state.canvasTitle, { timeout: 30000 });
    await closeDialogs(page);
    await page.evaluate(({ t, src }) => {
      const editor = window.tldrawApps[t];
      const assetId = `asset:eng2362${Date.now()}`;
      editor.createAssets([{ id: assetId, type: "image", typeName: "asset", props: { name: "eng2362.png", src, w: 200, h: 150, mimeType: "image/png", isAnimated: false }, meta: {} }]);
      const shapeId = `shape:eng2362${Date.now()}`;
      editor.createShape({ id: shapeId, type: "image", x: 0, y: 0, props: { assetId, w: 200, h: 150 } });
      editor.select(shapeId);
      const b = editor.getShapePageBounds(shapeId);
      const vp = editor.getViewportScreenBounds();
      editor.setCamera({ x: -b.x - b.w / 2 + vp.w / 2, y: -b.y - b.h / 2 + vp.h / 2, z: 1 });
    }, { t: state.canvasTitle, src: setup.src });
    await page.waitForTimeout(800);
    await page.locator('button[title="Convert to discourse node"]').click({ timeout: 10000 });
    const dialog = page.locator(".roamjs-canvas-dialog");
    await dialog.waitFor({ timeout: 15000 });
    await dialog.locator("button.bp3-button").filter({ hasNotText: /Confirm|Cancel/ }).first().click();
    await page.locator(".bp3-menu-item", { hasText: new RegExp(`^${NODE_TYPE_TEXT}$`) }).first().click();
    await dialog.locator("input, textarea").first().fill(state.nodeContent);
    await page.waitForTimeout(300);
    await dialog.locator("button", { hasText: "Confirm" }).click();
    await page.waitForTimeout(15000);

    const result = await page.evaluate(({ t }) => {
      const api = window.roamAlphaAPI;
      const shapes = window.tldrawApps[t].getCurrentPageShapes().map((s) => ({ type: s.type, uid: s.props.uid, title: s.props.title, imageUrl: s.props.imageUrl }));
      const dn = shapes.find((s) => s.type !== "image");
      const pageTree = dn ? api.pull("[:node/title :block/uid {:block/children [:block/string :block/order :block/heading {:block/children ...}]}]", [":block/uid", dn.uid]) : null;
      return { shapes, pageTree, queries: window.__ak };
    }, { t: state.canvasTitle });
    state.nodePageUid = result.pageTree?.[":block/uid"];
    return { setup, edits: { ...edits, original: "(saved)" }, ...result, logs };
  },
  async cleanup({ page }) {
    if (!state.edits) return { skipped: true };
    const verify = await page.evaluate(async ({ s, snapshotSrc }) => {
      const snapshot = new Function(`return (${snapshotSrc})`)();
      const api = window.roamAlphaAPI;
      window.__akRestore?.();
      for (const u of [s.nodePageUid, s.canvasUid, s.edits.qPage].filter(Boolean)) await api.data.page.delete({ page: { uid: u } });
      for (const u of s.edits.created) await api.data.block.delete({ block: { uid: u } });
      for (const { uid, text } of s.edits.updated) await api.data.block.update({ block: { uid, string: text } });
      await new Promise((r) => setTimeout(r, 1000));
      const now = snapshot(s.edits.typeUid);
      return {
        nodeTypeRestored: now === s.edits.original,
        canvasSettingsNow: window.roamjs.extension.queryBuilder.getDiscourseNodes().find((n) => n.type === s.edits.typeUid)?.canvasSettings,
        tempPagesGone: [s.nodePageUid, s.canvasUid, s.edits.qPage].filter(Boolean).every((u) => !api.pull("[:block/uid]", [":block/uid", u])),
      };
    }, { s: state, snapshotSrc: SNAPSHOT.toString() });
    return { verify };
  },
